 <?php if(!empty($questions[0]['import_headings'])): ?><details class="feature-card mb-3"><summary>Judul naskah (bukan soal)</summary><p class="text-break mt-2"><?php echo nl2br(html_escape(implode("\n",$questions[0]['import_headings']))); ?></p></details><?php endif; ?>
 <?php if($record['status']==='committed'): $result=json_decode($record['result_json'],TRUE); ?><p class="alert alert-success">Sudah tersimpan: <?php echo (int)$result['new']; ?> soal baru; <?php echo (int)$result['reused']; ?> baris memakai ID bank yang sudah ada. Memuat ulang halaman ini tidak menambah soal.</p><?php endif; ?>
 <?php foreach(array_slice($questions,($page-1)*20,20,TRUE) as $i=>$q): ?><article class="feature-card mb-3"><p class="eyebrow">Soal <?php echo (int)($q['import_number']??($i+1)); ?> · <?php echo html_escape(study_grade_label($q['grade_id'])); ?> · <?php echo html_escape($q['difficulty']); ?></p><h2 class="h6"><?php echo isset($known[$q['fingerprint']])?'Pakai ID #'.(int)$known[$q['fingerprint']]:'Baru (atau duplikat baris lain dalam berkas)'; ?></h2>
 <?php if(!empty($q['import_warnings'])): ?><ul class="alert alert-warning ps-5"><?php foreach($q['import_warnings'] as $warning): ?><li><?php echo html_escape($warning); ?></li><?php endforeach; ?></ul><?php endif; ?>
 <?php if(!empty($q['import_auto_images'])): ?><p class="small text-primary text-break"><i class="bi bi-images me-1" aria-hidden="true"></i>Gambar otomatis di atas soal: <?php echo html_escape(implode(', ',$q['import_auto_images'])); ?>. Periksa kecocokannya sebelum menyimpan.</p><?php endif; ?>
 <?php $layout=Question_media::layout($q['image'],$q['prompt'],$q['options']);
 $image_url=static function($index)use($record,$i){return site_url('kelola/bank-soal/impor/'.$record['token'].'/gambar/'.(int)$i.($index?'/'.$index:''));};
 $all_images=$q['image']?array_merge(array($q['image']),$q['image']['additional_images']??array()):array(); ?>
 <p class="fw-bold question-rich-text"><?php echo Question_media::render($q['prompt'],$layout,$image_url); ?></p>
 <?php if($layout['gallery']): ?><div class="row g-3 mb-3"><?php foreach($layout['gallery'] as $image_index): $image=$all_images[$image_index]; ?><figure class="col-md-6 mb-0"><img class="img-fluid rounded" width="400" loading="lazy" src="<?php echo $image_url($image_index); ?>" alt="Gambar <?php echo $image_index+1; ?> soal <?php echo (int)($q['import_number']??($i+1)); ?>"><figcaption class="small text-break mt-1">Gambar <?php echo $image_index+1; ?><?php echo isset($image['original_name'])?' · '.html_escape($image['original_name']):''; ?></figcaption></figure><?php endforeach; ?></div><?php endif; ?>
 <ol type="A"><?php foreach($q['options'] as $j=>$option): ?><li class="question-rich-text"><?php echo Question_media::render($option,$layout,$image_url,'pilihan '.chr(65+$j)); ?><?php if($j===$q['correct']): ?> <span class="badge text-bg-success">Kunci</span><?php endif; ?></li><?php endforeach; ?></ol><details><summary>Pembahasan</summary><p class="text-break"><?php echo $q['explanation']!==''?nl2br(html_escape($q['explanation'])):'Belum diisi. Dapat ditambahkan melalui edit bank soal.'; ?></p></details></article><?php endforeach; ?>
 <nav class="d-flex flex-wrap gap-3 mb-4" aria-label="Halaman pratinjau"><?php foreach(array(-1=>'Sebelumnya',1=>'Berikutnya') as $step=>$label):if($page+$step>=1&&$page+$step<=ceil(count($questions)/20)): ?><a class="btn btn-outline-primary" href="<?php echo site_url('kelola/bank-soal/impor/'.$record['token']).'?halaman='.($page+$step); ?>"><?php echo $label; ?></a><?php endif;endforeach; ?><span>Halaman <?php echo (int)$page; ?> / <?php echo (int)ceil(count($questions)/20); ?></span></nav>
 <?php if($record['status']==='preview'): ?><?php echo form_open('kelola/bank-soal/impor/'.$record['token'],array('class'=>'feature-card')); ?><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="publish" value="1" id="publish"><label class="form-check-label" for="publish">Aktifkan soal baru untuk latihan setelah impor (jika tidak, simpan draft)</label></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="confirm" value="1" id="confirm" required><label class="form-check-label" for="confirm">Saya telah memeriksa seluruh soal, gambar, pilihan/kunci, pembahasan serta hak penggunaannya.</label></div><button class="btn btn-primary" type="submit">Simpan ke bank<?php echo $record['exam_id']?' dan hubungkan ke ujian':''; ?></button><?php echo form_close(); ?><?php endif; ?></section>
